    }).collect::<anyhow::Result<Vec<_>>>()?;
    let config = temporary.path().join("resolution.yaml");
    fs::write(&config, format!("data_dir: {}\ncandidate_budget: 1000\n", serde_json::to_string(&root)?))?;
    let clean = run("clean", &config, &key);
    assert!(clean.status.success(), "{}", String::from_utf8_lossy(&clean.stderr));
    let cleaned = root.join(key.to_string()).join("cleaned/declarations");
    let funders_before = fs::read(cleaned.join("funders.parquet"))?;
    let funding_before = fs::read(cleaned.join("funding_entries.parquet"))?;
    let funders = rows(&cleaned.join("funders.parquet"))?;
    assert_eq!(funders.len(), names.len());
    assert_eq!(funders.iter().map(|row| row["name_raw"].as_str().unwrap()).collect::<BTreeSet<_>>(), names.into_iter().collect());
    assert!(funders.iter().all(|row| row["address_normalized"].is_null()));
    let resolved = run("resolve", &config, &key);
    assert!(resolved.status.success(), "{}", String::from_utf8_lossy(&resolved.stderr));
    let output = root.join(key.to_string()).join("resolved/declarations");
    let observations = rows(&output.join("observation_resolution.parquet"))?;
    assert_eq!(observations.len(), names.len());
    let identities = observations.iter().map(|row| (row["funder_id"].as_str().unwrap(), row["identity_id"].as_str().unwrap())).collect::<BTreeMap<_, _>>();
    let mut people = Vec::new();
    for surname in ["Farmer", "Sainsbury"] {
        let variants = funders.iter().filter(|row| row["name_raw"].as_str().unwrap().ends_with(surname)).collect::<Vec<_>>();
        assert_eq!(variants.len(), 3);
        let ids = variants.iter().map(|row| identities[row["funder_id"].as_str().unwrap()]).collect::<BTreeSet<_>>();
        assert_eq!(ids.len(), 1, "one identity for all {surname} variants");
        people.push(*ids.first().unwrap());
    }
    assert_ne!(people[0], people[1]);
    assert!(observations.iter().all(|row| row["identity_basis"] == "extracted_name_link"));
    let funding = rows(&cleaned.join("funding_entries.parquet"))?;
    let attribution = rows(&output.join("payment_attribution.parquet"))?;
    assert_eq!(funding.len(), names.len());
    assert_eq!(attribution.len(), funding.len());
    for payment in &funding {
        let attributed = attribution.iter().find(|row| row["funding_entry_id"] == payment["funding_entry_id"]).unwrap();
        assert_eq!(attributed["attribution_basis"], "donor");
        assert_eq!(attributed["identity_id"], identities[payment["donor_funder_id"].as_str().unwrap()]);
    }
    assert_eq!(fs::read(cleaned.join("funders.parquet"))?, funders_before);
    assert_eq!(fs::read(cleaned.join("funding_entries.parquet"))?, funding_before);
    for (path, bytes) in raw_before { assert_eq!(fs::read(path)?, bytes); }
    Ok(())
}
