                    left: left.key.clone(),
                    right: right.key.clone(),
                    probability,
                    name_level: 2,
                    address_level: 1,
                })
        })
        .collect();
    let scored =
        ScoredPairs::checked(pairs, serde_json::json!({"calibrated":false}), &scoring).unwrap();
    ResolvedDeclarations::from_scored(input, &scoring, scored, "test-run").unwrap()
